const gems=[[214,180,'#ffce62'],[1511,180,'#ed7bff'],[1512,661,'#74ffff']];let x=830,y=900,face=1,held=-1,target=-1,taps=0,done=new Set(),keys=[],last=0,fx=0,ending=0;
